# Let me try fitting different diagonal patterns
# Standard diagonal: c = offset + r (mod 24)
# Anti-diagonal: c = offset - r (mod 24)

data = [(0, 10), (1, 22), (2, 20), (3, 16), (4, 14), (5, 13), (6, 10), (7, 3), (8, 0)]

print("Standard diagonal (c = offset + r mod 24):")
for offset in range(24):
    errors = 0
    cols = []
    for r, c in data:
        pred = (offset + r) % 24
        cols.append(pred)
        if pred != c:
            errors += 1
    if errors < 4:
        print(f"  offset={offset}: columns={cols}, errors={errors}")

print("\nAnti-diagonal (c = offset - r mod 24):")
for offset in range(24):
    errors = 0
    cols = []
    for r, c in data:
        pred = (offset - r) % 24
        cols.append(pred)
        if pred != c:
            errors += 1
    if errors < 4:
        print(f"  offset={offset}: columns={cols}, errors={errors}")

# Hmm, neither fits well. Let me try slope = -2, -3, etc.
print("\nTrying c = offset + slope*r with various slopes:")
for slope in [-5, -4, -3, -2, -1, 1, 2, 3, 4, 5]:
    best_offset = 0
    best_err = 24
    for offset in range(24):
        err = 0
        cols = []
        for r, c in data:
            pred = (offset + slope * r) % 24
            cols.append(pred)
            if pred != c:
                err += 1
        if err < best_err:
            best_err = err
            best_offset = offset
    if best_err < 4:
        print(f"  slope={slope}: offset={best_offset}, errors={best_err}, cols={cols}")

# None of those fit well either. Let me try the pattern from row 0-4 vs row 4-8
